// A class plugin that is also a service: other plugins get it as ctx.counter (see stats).
// Switch it off and every plugin that injects 'counter' is unloaded by cordis; switch it on
// and they come back. Reloading this file does the same round trip.
import { Service } from 'cordis'
import type { Context } from 'cordis'
import type { TilrPluginClass } from 'tilr'

// The service's types, published from here: `inject: ['counter']` and `ctx.counter` in other
// plugins (stats) are typed by this. Types only, erased by the build.
declare module 'tilr' {
  interface TilrServices { counter: Counter }
}
declare module 'cordis' {
  interface Events { 'counter/change'(value: number): void }
}

const STEP = 1

class Counter extends Service {
  static provide = 'counter'
  static inject = ['ui']
  static author = 'dan'
  static tags = ['demo']
  // What `requires: { counter: '^0.1.0' }` in another plugin is checked against. In-tree, so the
  // core's version (build.mjs defines it); a plugin repo would define its own package.json's.
  static version = __TILR_VERSION__

  declare state: { value: number }
  declare render: () => void

  constructor(ctx: Context) {
    // cordis defaults the name to `static provide`, but its types want it spelled out.
    super(ctx, Counter.provide)
    // Callers reach this service through a proxy, so `this` in a method may be a derived
    // object: keep mutable state in one holder object, not in own fields.
    this.state = { value: 0 }

    const body = ctx.ui.tile({ title: 'counter' })
    const value = document.createElement('div')
    value.className = 'big'
    const button = document.createElement('button')
    button.textContent = `+${STEP}`
    button.onclick = () => this.add(STEP)
    body.append(value, button)
    this.render = () => { value.textContent = String(this.state.value) }
    this.render()
  }

  get value(): number {
    return this.state.value
  }

  add(n = STEP): void {
    this.state.value += n
    this.render()
    this.ctx.emit('counter/change', this.state.value)
  }
}

// `satisfies` checks the static metadata (provide, inject, author, tags) against TilrPluginClass.
export default Counter satisfies TilrPluginClass
